mapper.select:
select m.id, m.name, m.code, m.specification, m.material_category_id, m.unit_id, m.unit_extend_id, m.is_sub_material as subMaterial, m.status, m.merge_code from bm_material m left join bm_material_category c on m.material_category_id = c.id where m.is_deleted = 0
and m.name like concat('%',#{name},'%')
and m.code like concat('%',#{code},'%')
and m.merge_code like concat('%',#{mergeCode},'%')
and m.material_category_id in
#{mId}
and c.category_type = #{categoryType}
and m.status = #{status}
order by m.merge_code asc

SELECT m.id, m.NAME, m.CODE, m.material_category_id, m.platform_material_id, c.category_type FROM bm_material m LEFT JOIN bm_material_category c ON m.material_category_id = c.id WHERE m.is_deleted = 0
and c.category_type = #{type}
and m.platform_material_id in
#{pmid}

select m.id,m.code,m.name,m.platform_material_id,c.category_type from bm_material m left join bm_material_category c on m.material_category_id = c.id where m.is_deleted = 0
and c.category_type in
#{type}
and m.platform_material_id in
#{mid}

SELECT m.id, m.NAME, m.merge_code, m.specification, m.inner_packing_specification, m.packing_specification, m.product_mark FROM bm_material m LEFT JOIN bm_material_category c ON m.material_category_id = c.id WHERE m.is_deleted = 0 AND m.STATUS = TRUE
AND c.category_type = #{categoryType}
order by m.merge_code asc

SELECT m.id, m.NAME, m.merge_code, m.material_category_id as parentId, m.create_time, m.product_mark, m.specification FROM bm_material m LEFT JOIN bm_material_category c ON m.material_category_id = c.id WHERE m.is_deleted = 0 AND m.STATUS = TRUE
AND c.category_type = #{categoryType}
order by m.code desc

select m.id, m.name, m.code, m.specification, m.material_category_id, m.unit_id, m.unit_extend_id, m.is_sub_material as subMaterial, m.status, m.merge_code, m.create_time from bm_material m inner join bm_material_category c on m.material_category_id = c.id where m.is_deleted = 0 and c.is_deleted = 0 and m.id in
#{item}
and c.category_type = #{type}

SELECT m.id, m.NAME, m.merge_code, m.specification, m.inner_packing_specification, m.packing_specification FROM bm_material m left join bm_material_category c on m.material_category_id = c.id WHERE m.is_deleted = 0 AND m.STATUS = TRUE AND m.is_finish_product = TRUE
and c.category_type = #{categoryType}
order by m.merge_code asc

SELECT m.id, m.NAME, m.merge_code, m.material_category_id as parentId, m.create_time FROM bm_material m LEFT JOIN bm_material_category c ON m.material_category_id = c.id WHERE m.is_deleted = 0 AND m.STATUS = TRUE
AND c.category_type in
#{type}

select id from bm_material where is_deleted = 0 and STATUS = TRUE
and material_category_id in
#{categoryId}
and is_finish_product = #{finished}

SELECT m.id, m.NAME, m.merge_code, m.material_category_id as parentId, m.create_time FROM bm_material m LEFT JOIN bm_material_category c ON m.material_category_id = c.id WHERE m.is_deleted = 0 AND m.STATUS = TRUE
AND c.category_type = #{categoryType}
and m.is_finish_product = #{isFinishedProduct}
order by m.code desc

select m.*,c.category_type from bm_material m left join bm_material_category c on m.material_category_id = c.id where m.is_deleted = 0
and m.id in
#{id}
